import enUS from './en-US.js';
import esMX from './es-MX.js';
import frCA from './fr-CA.js';

/**
 * MenuMultiSelectPanel Locale Resources
 *
 * These JSON translation files can be imported by consumers who want to
 * integrate MenuMultiSelectPanel translations into their own i18n setup.
 *
 * ## Usage Example
 *
 * ```typescript
 * import i18n from 'i18next';
 * import { initReactI18next } from 'react-i18next';
 * import {
 *   menuMultiSelectPanelLocaleEnUS,
 *   menuMultiSelectPanelLocaleEsMX,
 *   menuMultiSelectPanelLocaleFrCA
 * } from '@walmart-dataventures/shared-components';
 *
 * i18n.use(initReactI18next).init({
 *   lng: 'en-US',
 *   fallbackLng: 'en-US',
 *   ns: ['MenuPanel', 'shared'],
 *   resources: {
 *     'en-US': {
 *       MenuPanel: menuMultiSelectPanelLocaleEnUS,
 *       shared: { ... }
 *     },
 *     'es-MX': {
 *       MenuPanel: menuMultiSelectPanelLocaleEsMX,
 *       shared: { ... }
 *     },
 *     'fr-CA': {
 *       MenuPanel: menuMultiSelectPanelLocaleFrCA,
 *       shared: { ... }
 *     }
 *   }
 * });
 * ```
 *
 * ## Changing the Active Locale
 *
 * To change the locale at runtime, use i18next's `changeLanguage()` method:
 *
 * ```typescript
 * import { useTranslation } from 'react-i18next';
 *
 * function LanguageSwitcher() {
 *   const { i18n } = useTranslation();
 *   return (
 *     <button onClick={() => i18n.changeLanguage('es-MX')}>
 *       Switch to Spanish
 *     </button>
 *   );
 * }
 * ```
 *
 * MenuPanel components will automatically use the active i18next locale.
 */

var menuMultiSelectPanelLocaleEnUS = enUS;
var menuMultiSelectPanelLocaleEsMX = esMX;
var menuMultiSelectPanelLocaleFrCA = frCA;

/**
 * All available locales as a map for programmatic access
 */
var menuMultiSelectPanelLocales = {
  'en-US': enUS,
  'es-MX': esMX,
  'fr-CA': frCA
};

export { menuMultiSelectPanelLocaleEnUS, menuMultiSelectPanelLocaleEsMX, menuMultiSelectPanelLocaleFrCA, menuMultiSelectPanelLocales };
